// Continuous random variates generated by inversion and similar: runif, rnorm, rexp, rlnorm, rlogis, rcauchy, rweibull.
//
// Parameter handling (whether a uniform is consumed for NaN, 0 or Inf) follows observed R output
// (verified by next in test/fixtures/random*.json).

import { expRand, normRand, unifRand } from "./rng.js";
import { generate } from "./common.js";
import { ddExp } from "../internal/ddexp.js";
import { ddAdd, ddLog, ddMulNum } from "../special/dd.js";
// Generated by `node scripts/option-keys.mjs --write` from the option types; do not edit (begin)
import { checkOptions } from "../internal/checkOptions.js";
const RUNIF_KEYS = ["min", "max"] as const;
const RNORM_KEYS = ["mean", "sd"] as const;
const REXP_KEYS = ["rate"] as const;
const RLNORM_KEYS = ["meanlog", "sdlog"] as const;
const RLOGIS_KEYS = ["location", "scale"] as const;
const RCAUCHY_KEYS = ["location", "scale"] as const;
const RWEIBULL_KEYS = ["scale"] as const;
// Generated by `node scripts/option-keys.mjs --write` (end)

/**
 * Random numbers from the uniform distribution. Equivalent to R's `runif()`.
 *
 * @param n Number of values to generate (fractions are truncated, as in R).
 * @param options.min Lower limit. Default `0`.
 * @param options.max Upper limit. Default `1`.
 * @returns An array of `n` values; `NaN` for invalid parameters.
 *
 * @example
 * ```ts
 * setSeed(1);
 * runif(3); // [0.2655087, 0.3721239, 0.5728534]
 * runif(2, { min: -1, max: 1 });
 * ```
 *
 * @category Random numbers
 */
export function runif(n: number, options: { min?: number; max?: number } = {}): number[] {
  checkOptions(options, RUNIF_KEYS, "runif"); // generated: option-keys.mjs
  const { min = 0, max = 1 } = options;
  return generate(n, () => {
    if (!Number.isFinite(min) || !Number.isFinite(max) || max < min) return NaN;
    if (min === max) return min;
    const u = unifRand();
    // a width that overflows (R returns Inf): the weighted mean of the ends instead
    return Number.isFinite(max - min) ? min + (max - min) * u : min * (1 - u) + max * u;
  });
}

export function rnorm1(mean: number, sd: number): number {
  if (Number.isNaN(mean) || !Number.isFinite(sd) || sd < 0) return NaN;
  if (sd === 0 || !Number.isFinite(mean)) return mean;
  const z = normRand();
  const x = mean + sd * z;
  // sd·Z can overflow although mean + sd·Z is in range (R gives ±Inf): the same sum halved (exact for such a large sd
  // and a mean that matters), rounded once and doubled
  return Number.isFinite(x) ? x : 2 * (mean / 2 + (sd / 2) * z);
}

/**
 * Random numbers from the normal distribution. Equivalent to R's `rnorm()`.
 *
 * Uses inversion (R's default `"Inversion"` normal kind), so the output matches R for the same seed.
 *
 * @param n Number of values to generate (fractions are truncated, as in R).
 * @param options.mean Mean. Default `0`.
 * @param options.sd Standard deviation. Default `1`.
 * @returns An array of `n` values; `NaN` for invalid parameters.
 *
 * @example
 * ```ts
 * setSeed(1);
 * rnorm(3); // [-0.6264538107423324, 0.18364332422208224, -0.8356286124100472]
 * rnorm(2, { mean: 10, sd: 2 });
 * ```
 *
 * @category Random numbers
 */
export function rnorm(n: number, options: { mean?: number; sd?: number } = {}): number[] {
  checkOptions(options, RNORM_KEYS, "rnorm"); // generated: option-keys.mjs
  const { mean = 0, sd = 1 } = options;
  return generate(n, () => rnorm1(mean, sd));
}

/**
 * Random numbers from the exponential distribution. Equivalent to R's `rexp()`.
 *
 * @param n Number of values to generate (fractions are truncated, as in R).
 * @param options.rate Rate. Default `1`.
 * @returns An array of `n` values; `NaN` for invalid parameters.
 *
 * @example
 * ```ts
 * setSeed(1);
 * rexp(2, { rate: 2 }); // [0.3775909, 0.5908214]
 * ```
 *
 * @category Random numbers
 */
export function rexp(n: number, options: { rate?: number } = {}): number[] {
  checkOptions(options, REXP_KEYS, "rexp"); // generated: option-keys.mjs
  const rate = options.rate ?? 1;
  const scale = 1 / rate;
  return generate(n, () => {
    // a positive rate below about 5.6e-309 has 1 / rate = Infinity: the variate itself (R gives NaN), which overflows
    // unless the exponential variate is small
    if (scale === Infinity && rate > 0) return expRand() / rate;
    if (!Number.isFinite(scale) || scale <= 0) return scale === 0 ? 0 : NaN;
    return scale * expRand();
  });
}

/**
 * Random numbers from the log-normal distribution. Equivalent to R's `rlnorm()`.
 *
 * @param n Number of values to generate (fractions are truncated, as in R).
 * @param options.meanlog Mean on the log scale. Default `0`.
 * @param options.sdlog Standard deviation on the log scale. Default `1`.
 * @returns An array of `n` values; `NaN` for invalid parameters.
 *
 * @example
 * ```ts
 * setSeed(1);
 * rlnorm(2, { meanlog: 0, sdlog: 1 }); // [0.5344838, 1.201587]
 * ```
 *
 * @category Random numbers
 */
export function rlnorm(n: number, options: { meanlog?: number; sdlog?: number } = {}): number[] {
  checkOptions(options, RLNORM_KEYS, "rlnorm"); // generated: option-keys.mjs
  const { meanlog = 0, sdlog = 1 } = options;
  return generate(n, () => {
    if (Number.isNaN(meanlog) || !Number.isFinite(sdlog) || sdlog < 0) return NaN;
    return Math.exp(rnorm1(meanlog, sdlog));
  });
}

/**
 * Random numbers from the logistic distribution. Equivalent to R's `rlogis()`.
 *
 * @param n Number of values to generate (fractions are truncated, as in R).
 * @param options.location Location. Default `0`.
 * @param options.scale Scale. Default `1`.
 * @returns An array of `n` values; `NaN` for invalid parameters.
 *
 * @example
 * ```ts
 * setSeed(1);
 * rlogis(2, { location: 0, scale: 1 }); // [-1.017531, -0.523116]
 * ```
 *
 * @category Random numbers
 */
export function rlogis(n: number, options: { location?: number; scale?: number } = {}): number[] {
  checkOptions(options, RLOGIS_KEYS, "rlogis"); // generated: option-keys.mjs
  const { location = 0, scale = 1 } = options;
  return generate(n, () => {
    if (Number.isNaN(location) || !Number.isFinite(scale)) return NaN;
    // a negative scale defines no distribution (dlogis, plogis and qlogis give NaN; R draws from it). The uniform R
    // draws is drawn as well, so the stream stays R's
    if (scale < 0) {
      unifRand();
      return NaN;
    }
    if (scale === 0 || !Number.isFinite(location)) return location;
    const u = unifRand();
    return location + scale * Math.log(u / (1 - u));
  });
}

/**
 * Random numbers from the Cauchy distribution. Equivalent to R's `rcauchy()`.
 *
 * @param n Number of values to generate (fractions are truncated, as in R).
 * @param options.location Location. Default `0`.
 * @param options.scale Scale. Default `1`.
 * @returns An array of `n` values; `NaN` for invalid parameters.
 *
 * @example
 * ```ts
 * setSeed(1);
 * rcauchy(2, { location: 0, scale: 1 }); // [1.10252, 2.353831]
 * ```
 *
 * @category Random numbers
 */
export function rcauchy(n: number, options: { location?: number; scale?: number } = {}): number[] {
  checkOptions(options, RCAUCHY_KEYS, "rcauchy"); // generated: option-keys.mjs
  const { location = 0, scale = 1 } = options;
  return generate(n, () => {
    if (Number.isNaN(location) || !Number.isFinite(scale) || scale < 0) return NaN;
    if (scale === 0 || !Number.isFinite(location)) return location;
    return location + scale * Math.tan(Math.PI * unifRand());
  });
}

/**
 * Random numbers from the Weibull distribution. Equivalent to R's `rweibull()`.
 *
 * @param n Number of values to generate (fractions are truncated, as in R).
 * @param shape Shape parameter (required, as in R).
 * @param options.scale Scale. Default `1`.
 * @returns An array of `n` values; `NaN` for invalid parameters.
 *
 * @example
 * ```ts
 * setSeed(1);
 * rweibull(2, 2, { scale: 1 }); // [1.151568, 0.9942477]
 * ```
 *
 * @category Random numbers
 */
export function rweibull(n: number, shape: number, options: { scale?: number } = {}): number[] {
  checkOptions(options, RWEIBULL_KEYS, "rweibull"); // generated: option-keys.mjs
  const { scale = 1 } = options;
  return generate(n, () => {
    // an invalid shape (or a negative scale) is NaN also with scale = 0 (R returns 0 there; no variate is drawn either
    // way); scale = 0 is the point mass at 0
    if (!(shape > 0) || !(scale >= 0)) return NaN;
    if (!Number.isFinite(shape) || !Number.isFinite(scale) || scale === 0) {
      return scale === 0 ? 0 : NaN;
    }
    const e = -Math.log(unifRand());
    const p = Math.pow(e, 1 / shape);
    // for a small shape the power can overflow although the variate is in range for a small scale (R gives Inf): in
    // logs then, double-double so that the large log keeps its digits
    if (p !== Infinity) return scale * p;
    return ddExp(ddAdd(ddLog([scale, 0]), ddMulNum(ddLog([e, 0]), 1 / shape)))[0];
  });
}
